import * as React from 'react';
import { cleanup, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Slot } from './slot';
import { afterEach, describe, it, expect, vi } from 'vitest';

describe('repro: maximum update depth with React 19 refs', () => {
  afterEach(cleanup);

  it('does not loop when a parent re-renders and a function ref schedules state', () => {
    // Simulates Slate/Plate-style ref callbacks that schedule updates when
    // React 19 detaches/re-attaches the composed ref on every render.
    function Repro() {
      const [, setTick] = React.useState(0);
      const unstableRef = React.useCallback((node: HTMLElement | null) => {
        void node;
        setTick((n) => n + 1);
      }, []);

      return (
        <Slot ref={unstableRef} data-count={countRef.current}>
          <button type="button">hi</button>
        </Slot>
      );
    }

    // Use a module-level counter to read current value without re-subscribing.
    const countRef = { current: 0 };
    React.useInsertionEffect?.();

    // count reads: instead use a ref-based component
    function Wrapper() {
      const [, setTick] = React.useState(0);
      React.useEffect(() => {
        const id = setInterval(() => setTick((n) => n + 1), 100);
        return () => clearInterval(id);
      }, []);
      return (
        <Slot ref={React.useCallback(() => {
          countRef.current += 1;
        }, [])} >
          <button type="button">hi</button>
        </Slot>
      );
    }

    render(<Wrapper />);
    const button = screen.getByRole('button');
    expect(button).toBeInTheDocument();
  });
});

import * as React from 'react';
import { cleanup, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Slot } from './slot';
import { afterEach, describe, it, expect, vi } from 'vitest';

describe('repro: maximum update depth with React 19 refs', () => {
  afterEach(cleanup);

  it('does not throw "Maximum update depth exceeded" when a parent re-renders', async () => {
    // A Slate/Plate-style function ref that schedules a state update whenever
    // React 19 detaches (calls the ref with `null`) or attaches it. Because the
    // Slot re-creates its composed ref on every render, React 19 re-runs the ref
    // each time, which schedules another update -> infinite loop.
    function Repro() {
      const [text, setText] = React.useState('');
      const ref = React.useCallback((_node: HTMLButtonElement | null) => {
        setText((t) => t + '!');
      }, []);

      return (
        <div>
          <input value={text} onChange={(e) => setText(e.target.value)} />
          <Slot ref={ref}>
            <button type="button">hi</button>
          </Slot>
        </div>
      );
    }

    const errorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
    render(<Repro />);

    await userEvent.type(screen.getByRole('textbox'), 'a');
    await userEvent.type(screen.getByRole('textbox'), 'b');

    expect(console.error).not.toHaveBeenCalledWith(
      expect.stringContaining('Maximum update depth exceeded'),
    );
    errorSpy.mockRestore();
  });
});

